mapper.select:
select adjust_id, adjust_code, adjust_type, source_batch_id, source_batch_code, material_id,
       status, reason, execute_time, execute_by, del_flag, create_by, create_time, update_by, update_time, remark
from food_batch_adjust

    del_flag = '0'

        AND adjust_code like concat('%', #{adjustCode}, '%')


        AND adjust_type = #{adjustType}


        AND source_batch_code like concat('%', #{sourceBatchCode}, '%')


        AND material_id = #{materialId}


        AND status = #{status}


order by adjust_id desc

mapper.update:
update food_batch_adjust
status = #{status}, reason = #{reason}, execute_time = #{executeTime}, execute_by = #{executeBy}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark},
where adjust_id = #{adjustId}

update food_batch_adjust_item
target_batch_id = #{targetBatchId}, target_batch_code = #{targetBatchCode}, remark = #{remark},
where item_id = #{itemId}
